insert into public.reference_test_cases (code, module_id, name, calculation, input, expected_output, dataset) values ('RC-M1-01', 'M1_REDUCTION_GENERALE', 'Mode rapide : 1 salarié entre 1,3 et 1,6 SMIC en 2024, aucune réduction déclarée', 'SMIC annuel = 12,40 × 151,67 × 12 = 22 568,50. Haut : C(1,3) = 0,32/0,6 × (1,6/1,3 − 1) = 0,1231 → 0,1231 × 1,3 × 22 568,50 = 3 611,64. Central : C(1,45) = 0,0552 → 1 806,38. Bas : C(1,6⁻) ≈ 0.', '{"asOfDate":"2027-01-15","mode":"rapide","company":{"siren":null,"nafCode":null,"headcountByYear":{"2024":10}},"quick":{"years":[{"year":2024,"averageHeadcount":10,"declaredGeneralReduction":0,"brackets":[{"bracket":"1_3_1_6","employeeCount":1,"partTimeShare":0}]}]}}'::jsonb, '[{"year":2024,"status":"estime","amounts":{"low":0,"central":1806.38,"high":3611.64}}]'::jsonb, 'test') on conflict (code) do update set input = excluded.input, expected_output = excluded.expected_output, calculation = excluded.calculation;
